//! The permutation: its parameters, round constants and linear layers.

use core::ops::{Add, AddAssign, Mul};

use crate::field::{M31, P};

/// The state's width, in words.
pub const N_STATE: usize = 16;
/// The partial rounds.
pub const N_PARTIAL_ROUNDS: usize = 14;
/// The full rounds on each side of the partial rounds.
pub const N_HALF_FULL_ROUNDS: usize = 4;
/// The full rounds.
pub const FULL_ROUNDS: usize = 2 * N_HALF_FULL_ROUNDS;

